/*
 * A179910  Primes with two embedded primes.
 * https://oeis.org/A179910
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) = number of primes p such that the set of prime integers
 *            generated by contiguous proper substrings of p has size 2
 * Range:     u8 n <= 14, u16 n <= 989, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   build_primes_upto, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>

#include "../utils/build_primes_upto.h"
#include "../utils/is_prime_big.h"

static uint64_t *prime_array = NULL;
static size_t      prime_cnt   = 0;
static idx_t       prime_limit = 2000000; /* initial upper bound */

static seq_t *special = NULL;
static size_t  special_cnt = 0;
static size_t  special_cap = 0;

static idx_t current_prime_index = 0;
static bool  primes_initialized = false;

/* Generate primes up to limit using the utility build_primes_upto. */
static void init_primes(void)
{
    if (primes_initialized)
        return;

    if (prime_array)
        free(prime_array);
    build_primes_upto(prime_limit, &prime_array, &prime_cnt);
    primes_initialized = true;
}

/* Return true iff p has exactly two distinct prime substrings. */
static bool has_two_primes(seq_t p)
{
    /* extract decimal digits into array (most significant first) */
    uint8_t digs[64];
    int len = 0;
    seq_t tmp = p;
    if (tmp == 0)
        return false;
    while (tmp > 0) {
        digs[len++] = (uint8_t)(tmp % 10);
        tmp /= 10;
    }
    for (int i = 0; i < len / 2; ++i) {
        uint8_t t = digs[i];
        digs[i] = digs[len - 1 - i];
        digs[len - 1 - i] = t;
    }

    /* collect distinct prime substrings */
    seq_t primes_list[64];
    int  primes_seen = 0;

    for (int i = 0; i < len; ++i) {
        seq_t val = 0;
        for (int j = i; j < len; ++j) {
            val = val * 10 + digs[j];
            if (i == 0 && j == len - 1) /* skip full number itself */
                continue;
            if (is_prime_big(val)) {
                /* check if already seen */
                bool seen = false;
                for (int k = 0; k < primes_seen; ++k)
                    if (primes_list[k] == val) {
                        seen = true;
                        break;
                    }
                if (!seen) {
                    if (primes_seen == 64)
                        return false; /* shouldn't happen */
                    primes_list[primes_seen++] = val;
                    if (primes_seen > 2)
                        return false;     /* more than two distinct primes */
                }
            }
        }
    }
    return primes_seen == 2;
}

seq_t a(idx_t n)
{
    if (n == 0) /* undefined, but return 0 to avoid UB */
        return 0U;

    /* Ensure primes up to initial limit are ready. */
    init_primes();

    /* Generate special primes until we have n of them. */
    while (special_cnt < n) {
        /* If we have exhausted current primes, double the limit. */
        if (current_prime_index >= prime_cnt) {
            prime_limit *= 2;
            init_primes(); /* reinit with larger limit */
            /* current_prime_index remains valid because new array
               extends the previous one. */
        }

        uint64_t p64 = prime_array[current_prime_index++];
        seq_t p = (seq_t)p64;

        if (has_two_primes(p)) {
            /* Append to special vector. */
            if (special_cnt >= special_cap) {
                special_cap = special_cap ? special_cap * 2 : 16;
                special = (seq_t *)realloc(special, special_cap * sizeof(seq_t));
            }
            special[special_cnt++] = p;
        }
    }

    return special[n - 1];
}
